costs_data = cells('W0::Leaf costs', 'E30:F32')
costs = {row[0]: row[1] for row in costs_data}
rules = {}
for p, c, u in rules_data:
    if p not in rules:
        rules[p] = []
    rules[p].append((c, u))

def get_costs(part):
    if part in costs:
        return {part: costs[part]}
    if part not in rules:
        return {}
    total = {}
    for child, mult in rules[part]:
        sub = get_costs(child)
        for k, v in sub.items():
            total[k] = total.get(k, 0.0) + v * mult
    return total

crate_costs = get_costs('Crate')
beacon_costs = get_costs('Beacon')
total_crate = sum(crate_costs.values())
total_beacon = sum(beacon_costs.values())
result = round(total_crate - total_beacon, 2)

